def trace(s):
    path=[]; c=s; seen={s}
    while True:
        nbs=[(c[0]+dy,c[1]+dx) for dy,dx in[(1,0),(-1,0),(0,1),(0,-1)] if (c[0]+dy,c[1]+dx) in cells-seen]
