def solve(I):
    h=len(I); w=len(I[0])
    mk=[(i,j) for i in range(h) for j in range(w) if I[i][j]==2][0]
    O=[r[:] for r in I]
    def beam(start, d):
        p=start; steps=0
        while steps<h*w*6:
            steps+=1
            if not(0<=p[0]<h and 0<=p[1]<w): break
            q=(p[0]+d[0],p[1]+d[1])
            if not(0<=q[0]<h and 0<=q[1]<w) or I[q[0]][q[1]]!=0: break
            O[p[0]][p[1]]=2
            p=q
        return p,steps
    # fires only into a bar
    def fire():
        res=[]
        for d in [(-1,0),(1,0),(0,-1),(0,1)]:
            q=(mk[0]+d[0],mk[1]+d[1])
            if 0<=q[0]<h and 0<=q[1]<w and I[q[0]][q[1]]==8:
                res.append((mk,d,q))
        return res
    fronts=[]
    fronts+=fire()
    for _ in range(h*w*6):
        if not fronts: break
        newfronts=[]
        for p,d,last in fronts:
            q=(p[0]+d[0],p[1]+d[1])
            if not(0<=q[0]<h and 0<=q[1]<w) or I[q[0]][q[1]]==8:
                # blocked: try perpendicular rolls
                for dw in [(0,1),(0,-1)] if d[0]!=0 else [(1,0),(-1,0)]:
                    rp=p; gated=False
                    while True:
                        ahead=(rp[0]+d[0],rp[1]+d[1])
                        if not(0<=ahead[0]<h and 0<=ahead[1]<w) or I[ahead[0]][ahead[1]]!=8:
                            if ahead[0]>=0 and ahead[0]<h and 0<=ahead[1]<w and I[ahead[0]][ahead[1]]==0:
                                gated=True
                            break
                        rp=(rp[0]+dw[0],rp[1]+dw[1])
                        if not(0<=rp[0]<h and 0<=rp[1]<w): break
                    if gated and 0<=rp[0]+d[0]<h and 0<=rp[1]+d[1]<w and I[rp[0]+d[0]][rp[1]+d[1]]==0:
                        newfronts.append((rp,d,(rp,p)))
        fronts=newfronts
    return O
